// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MStableYieldSource, ISavingsContractV2} from "../src/MStableYieldSource.sol";

contract InvMutTest is Test {
    MStableYieldSource c;
    function setUp() public { c = new MStableYieldSource(ISavingsContractV2(address(new __InvMutHandleStub()))); }
    function testFuzz_property(uint256 amount, address actor, address beneficiary) public {
        vm.assume(actor != address(0));
        vm.assume(beneficiary != address(0));
        vm.assume(actor != beneficiary);
        vm.assume(actor != address(c));
        vm.assume(beneficiary != address(c));
        amount = bound(amount, 1, 1e30);
        vm.prank(actor);
        try c.supplyTokenTo(amount, beneficiary) {
            // A fresh supplier's own credit balance must remain zero: credits go
            // solely to the designated beneficiary, never to the caller itself.
            assertTrue(c.imBalances(actor) == 0);
        } catch {
            assertTrue(true);
        }
    }
}
